 5→import java.time.Duration;
 6→import java.time.Instant;
 7→import java.util.Objects;
 8→import java.util.Set;
 9→import java.util.concurrent.ConcurrentHashMap;
10→
11→/**
12→ * Tracks departed nodes and manages the grace period before permanent removal.
13→ *
14→ * <p>
15→ * Contract: Records node departures with timestamps. A departed node is considered in
16→ * grace period if the configured duration has not elapsed since departure. After grace
17→ * period expiry, the departure is permanent. If a node returns during grace, its
18→ * departure record is cleared. Grace period controls cleanup timing, not ownership
19→ * assignment — partitions are eagerly reassigned on departure.
20→ *
21→ * <p>
22→ * Thread-safe: uses concurrent data structures.
23→ *
24→ * <p>
25→ * Governed by: {@code .decisions/rebalancing-grace-period-strategy/adr.md}
26→ */
27→public final class GracePeriodManager {
28→
29→    private final Duration gracePeriod;
30→    private final ConcurrentHashMap<NodeAddress, Instant> departures = new ConcurrentHashMap<>();
31→
32→    /**
33→     * Creates a grace period manager with the specified duration.
34→     *
35→     * @param gracePeriod the grace period duration; must not be null and must be positive
36→     */
37→    public GracePeriodManager(Duration gracePeriod) {
38→        Objects.requireNonNull(gracePeriod, "gracePeriod must not be null");
39→        if (gracePeriod.isNegative() || gracePeriod.isZero()) {
40→            throw new IllegalArgumentException("gracePeriod must be positive");
41→        }
42→        this.gracePeriod = gracePeriod;
43→    }
44→
45→    /**
46→     * Records the departure of a node at the given time.
47→     *
48→     * @param node       the departed node's address; must not be null
49→     * @param departedAt the instant of departure; must not be null
50→     */
51→    public void recordDeparture(NodeAddress node, Instant departedAt) {
52→        throw new UnsupportedOperationException("Not implemented");
53→    }
54→
55→    /**
56→     * Returns whether the given node is currently in its grace period.
57→     *
58→     * @param node the node address to check; must not be null
59→     * @return {@code true} if the node departed and the grace period has not expired
60→     */
61→    public boolean isInGracePeriod(NodeAddress node) {
62→        throw new UnsupportedOperationException("Not implemented");
63→    }
64→
65→    /**
66→     * Returns the set of nodes whose grace period has expired.
67→     *
68→     * @return a set of node addresses with expired grace periods; never null
69→     */
70→    public Set<NodeAddress> expiredDepartures() {
71→        throw new UnsupportedOperationException("Not implemented");
72→    }
73→
74→    /**
75→     * Records the return of a previously departed node, clearing its departure record.
76→     *
77→     * @param node the returning node's address; must not be null
78→     */
79→    public void recordReturn(NodeAddress node) {
80→        throw new UnsupportedOperationException("Not implemented");
81→    }
82→}
