package jlsm.engine.cluster;

import jlsm.engine.cluster.internal.RendezvousOwnership;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import java.time.Instant;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Tests for {@link RendezvousOwnership} — deterministic partition-to-node assignment
 * via Rendezvous (Highest Random Weight) hashing.
 */
final class RendezvousOwnershipTest {

    private RendezvousOwnership ownership;

    private static final NodeAddress NODE_A = new NodeAddress("node-a", "host-a", 8001);
    private static final NodeAddress NODE_B = new NodeAddress("node-b", "host-b", 8002);
    private static final NodeAddress NODE_C = new NodeAddress("node-c", "host-c", 8003);
    private static final NodeAddress NODE_D = new NodeAddress("node-d", "host-d", 8004);
    private static final Instant NOW = Instant.parse("2026-03-20T00:00:00Z");

    @BeforeEach
    void setUp() {
        ownership = new RendezvousOwnership();
    }

    // --- Determinism ---

    @Test
    void assignOwner_sameInputProducesSameOutput() {
        MembershipView view = viewOf(1, NODE_A, NODE_B, NODE_C);
        NodeAddress first = ownership.assignOwner("table-1", view);
        NodeAddress second = ownership.assignOwner("table-1", view);
        assertNotNull(first);
        assertEquals(first, second, "Same inputs must produce same assignment");
    }

    @Test
    void assignOwner_deterministicAcrossInstances() {
        MembershipView view = viewOf(1, NODE_A, NODE_B, NODE_C);
        RendezvousOwnership other = new RendezvousOwnership();
        NodeAddress fromThis = ownership.assignOwner("table-x", view);
        NodeAddress fromOther = other.assignOwner("table-x", view);
        assertEquals(fromThis, fromOther, "Different instances must produce identical assignments");
    }

    @Test
    void assignOwner_differentIdsCanMapToDifferentNodes() {
        MembershipView view = viewOf(1, NODE_A, NODE_B, NODE_C);
        Set<NodeAddress> assigned = new HashSet<>();
        // With enough IDs we should see at least 2 different nodes
        for (int i = 0; i < 100; i++) {
            assigned.add(ownership.assignOwner("id-" + i, view));
        }
        assertTrue(assigned.size() >= 2,
                "100 different IDs across 3 nodes should hit at least 2 different nodes");
    }

    @Test
    void assignOwner_singleNode() {
        MembershipView view = viewOf(1, NODE_A);
        NodeAddress owner = ownership.assignOwner("table-1", view);
        assertEquals(NODE_A, owner, "Single node must be the owner");
    }

    // --- Minimal movement on view change ---

    @Test
    void assignOwner_addingNodeMovesMinimalKeys() {
        MembershipView viewBefore = viewOf(1, NODE_A, NODE_B, NODE_C);
        MembershipView viewAfter = viewOf(2, NODE_A, NODE_B, NODE_C, NODE_D);

        int moved = 0;
        final int total = 1000;
        for (int i = 0; i < total; i++) {
            String id = "partition-" + i;
            NodeAddress before = ownership.assignOwner(id, viewBefore);
            NodeAddress after = ownership.assignOwner(id, viewAfter);
            if (!before.equals(after)) {
                moved++;
            }
        }
        // Adding 1 node to 3: ideal movement is ~K/N = 1000/4 = 250
        // Allow generous range [100, 500] for hash distribution variance
        assertTrue(moved > 0, "Some keys must move when a node is added");
        assertTrue(moved < total / 2,
                "Movement should be roughly K/N, not catastrophic. Moved: " + moved);
    }

    @Test
    void assignOwner_removingNodeMovesOnlyDepartedKeys() {
        MembershipView viewBefore = viewOf(1, NODE_A, NODE_B, NODE_C);
        MembershipView viewAfter = viewOf(2, NODE_A, NODE_B);

        int moved = 0;
        int movedFromNonDeparted = 0;
        final int total = 1000;
        for (int i = 0; i < total; i++) {
            String id = "partition-" + i;
            NodeAddress before = ownership.assignOwner(id, viewBefore);
            NodeAddress after = ownership.assignOwner(id, viewAfter);
            if (!before.equals(after)) {
                moved++;
                if (!before.equals(NODE_C)) {
                    movedFromNonDeparted++;
                }
            }
        }
        assertTrue(moved > 0, "Some keys must move when a node departs");
        assertEquals(0, movedFromNonDeparted,
                "Only keys previously on the departed node should move");
    }

    // --- IllegalStateException on no live members ---

    @Test
    void assignOwner_emptyViewThrows() {
        MembershipView view = new MembershipView(1, Set.of(), NOW);
        assertThrows(IllegalStateException.class,
                () -> ownership.assignOwner("table-1", view));
    }

    @Test
    void assignOwner_onlySuspectedMembersThrows() {
        Member suspected = new Member(NODE_A, MemberState.SUSPECTED, 0);
        MembershipView view = new MembershipView(1, Set.of(suspected), NOW);
        assertThrows(IllegalStateException.class,
                () -> ownership.assignOwner("table-1", view));
    }

    @Test
    void assignOwner_onlyDeadMembersThrows() {
        Member dead = new Member(NODE_A, MemberState.DEAD, 0);
        MembershipView view = new MembershipView(1, Set.of(dead), NOW);
        assertThrows(IllegalStateException.class,
                () -> ownership.assignOwner("table-1", view));
    }

    // --- Input validation ---

    @Test
    void assignOwner_nullIdThrows() {
        MembershipView view = viewOf(1, NODE_A);
        assertThrows(NullPointerException.class,
                () -> ownership.assignOwner(null, view));
    }

    @Test
    void assignOwner_emptyIdThrows() {
        MembershipView view = viewOf(1, NODE_A);
        assertThrows(IllegalArgumentException.class,
                () -> ownership.assignOwner("", view));
    }

    @Test
    void assignOwner_nullViewThrows() {
        assertThrows(NullPointerException.class,
                () -> ownership.assignOwner("table-1", null));
    }

    // --- assignOwners (replica ranking) ---

    @Test
    void assignOwners_returnsOrderedListWithNoDuplicates() {
        MembershipView view = viewOf(1, NODE_A, NODE_B, NODE_C);
        List<NodeAddress> owners = ownership.assignOwners("table-1", view, 3);
        assertEquals(3, owners.size());
        assertEquals(3, new HashSet<>(owners).size(), "No duplicates allowed");
    }

    @Test
    void assignOwners_firstElementMatchesSingleOwner() {
        MembershipView view = viewOf(1, NODE_A, NODE_B, NODE_C);
        NodeAddress single = ownership.assignOwner("table-1", view);
        List<NodeAddress> ranked = ownership.assignOwners("table-1", view, 3);
        assertEquals(single, ranked.getFirst(),
                "First element of ranked list must match assignOwner result");
    }

    @Test
    void assignOwners_capsAtLiveMemberCount() {
        MembershipView view = viewOf(1, NODE_A, NODE_B);
        List<NodeAddress> owners = ownership.assignOwners("table-1", view, 5);
        assertEquals(2, owners.size(), "Cannot assign more replicas than live members");
    }

    @Test
    void assignOwners_replicasMustBeAtLeastOne() {
        MembershipView view = viewOf(1, NODE_A);
        assertThrows(IllegalArgumentException.class,
                () -> ownership.assignOwners("table-1", view, 0));
    }

    @Test
    void assignOwners_noLiveMembersThrows() {
        MembershipView view = new MembershipView(1, Set.of(), NOW);
        assertThrows(IllegalStateException.class,
                () -> ownership.assignOwners("table-1", view, 1));
    }

    @Test
    void assignOwners_deterministicRanking() {
        MembershipView view = viewOf(1, NODE_A, NODE_B, NODE_C);
        List<NodeAddress> first = ownership.assignOwners("table-1", view, 3);
        List<NodeAddress> second = ownership.assignOwners("table-1", view, 3);
        assertEquals(first, second, "Ranking must be deterministic");
    }

    // --- Cache keyed on epoch ---

    @Test
    void assignOwner_cachedByEpoch() {
        MembershipView view = viewOf(1, NODE_A, NODE_B, NODE_C);
        NodeAddress first = ownership.assignOwner("table-1", view);
        // Same epoch, same view — should use cached result
        NodeAddress second = ownership.assignOwner("table-1", view);
        assertEquals(first, second);
    }

    // --- evictBefore ---

    @Test
    void evictBefore_clearsOldEpochCache() {
        MembershipView view1 = viewOf(1, NODE_A, NODE_B);
        MembershipView view2 = viewOf(5, NODE_A, NODE_B, NODE_C);

        // Populate cache for both epochs
        ownership.assignOwner("table-1", view1);
        ownership.assignOwner("table-1", view2);

        // Evict entries older than epoch 5
        ownership.evictBefore(5);

        // Epoch 5 should still work (cache or recompute — either is fine)
        NodeAddress afterEvict = ownership.assignOwner("table-1", view2);
        assertNotNull(afterEvict);
    }

    @Test
    void evictBefore_doesNotThrowOnEmptyCache() {
        assertDoesNotThrow(() -> ownership.evictBefore(100));
    }

    // --- Mixed member states ---

    @Test
    void assignOwner_ignoresNonAliveMembers() {
        Member alive = new Member(NODE_A, MemberState.ALIVE, 0);
        Member suspected = new Member(NODE_B, MemberState.SUSPECTED, 0);
        Member dead = new Member(NODE_C, MemberState.DEAD, 0);
        MembershipView view = new MembershipView(1, Set.of(alive, suspected, dead), NOW);

        NodeAddress owner = ownership.assignOwner("table-1", view);
        assertEquals(NODE_A, owner, "Only ALIVE members should be considered");
    }

    // --- Helper ---

    private static MembershipView viewOf(long epoch, NodeAddress... nodes) {
        Set<Member> members = new HashSet<>();
        for (NodeAddress addr : nodes) {
            members.add(new Member(addr, MemberState.ALIVE, 0));
        }
        return new MembershipView(epoch, members, NOW);
    }
}

package jlsm.engine.cluster;

import jlsm.engine.cluster.internal.PhiAccrualFailureDetector;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Tests for {@link PhiAccrualFailureDetector}.
 */
class PhiAccrualFailureDetectorTest {

    private static final NodeAddress NODE_A =
            new NodeAddress("node-a", "localhost", 7001);
    private static final NodeAddress NODE_B =
            new NodeAddress("node-b", "localhost", 7002);

    // --- Constructor validation ---

    @Test
    void constructorRejectsWindowSizeBelowTwo() {
        assertThrows(IllegalArgumentException.class,
                () -> new PhiAccrualFailureDetector(1));
    }

    @Test
    void constructorRejectsWindowSizeZero() {
        assertThrows(IllegalArgumentException.class,
                () -> new PhiAccrualFailureDetector(0));
    }

    @Test
    void constructorRejectsNegativeWindowSize() {
        assertThrows(IllegalArgumentException.class,
                () -> new PhiAccrualFailureDetector(-5));
    }

    @Test
    void constructorAcceptsWindowSizeTwo() {
        assertDoesNotThrow(() -> new PhiAccrualFailureDetector(2));
    }

    // --- phi returns 0.0 until >= 2 heartbeats ---

    @Test
    void phiReturnsZeroForUnknownNode() {
        var detector = new PhiAccrualFailureDetector(10);
        assertEquals(0.0, detector.phi(NODE_A));
    }

    @Test
    void phiReturnsZeroAfterSingleHeartbeat() {
        var detector = new PhiAccrualFailureDetector(10);
        detector.recordHeartbeat(NODE_A);
        assertEquals(0.0, detector.phi(NODE_A));
    }

    // --- Input validation ---

    @Test
    void recordHeartbeatRejectsNull() {
        var detector = new PhiAccrualFailureDetector(10);
        assertThrows(NullPointerException.class,
                () -> detector.recordHeartbeat(null));
    }

    @Test
    void phiRejectsNull() {
        var detector = new PhiAccrualFailureDetector(10);
        assertThrows(NullPointerException.class,
                () -> detector.phi(null));
    }

    @Test
    void isAvailableRejectsNullNode() {
        var detector = new PhiAccrualFailureDetector(10);
        assertThrows(NullPointerException.class,
                () -> detector.isAvailable(null, 8.0));
    }

    @Test
    void isAvailableRejectsNonPositiveThreshold() {
        var detector = new PhiAccrualFailureDetector(10);
        assertThrows(IllegalArgumentException.class,
                () -> detector.isAvailable(NODE_A, 0.0));
        assertThrows(IllegalArgumentException.class,
                () -> detector.isAvailable(NODE_A, -1.0));
    }

    // --- phi computation with known intervals ---

    @Test
    void phiIsFiniteAfterTwoHeartbeats() throws InterruptedException {
        var detector = new PhiAccrualFailureDetector(10);
        detector.recordHeartbeat(NODE_A);
        Thread.sleep(50);
        detector.recordHeartbeat(NODE_A);
        // phi should be a non-negative finite value now (close to zero since
        // we just recorded a heartbeat)
        double phi = detector.phi(NODE_A);
        assertTrue(phi >= 0.0, "phi should be non-negative, got: " + phi);
        assertTrue(Double.isFinite(phi), "phi should be finite, got: " + phi);
    }

    @Test
    void phiIncreasesWithElapsedTime() throws InterruptedException {
        var detector = new PhiAccrualFailureDetector(10);
        // Record heartbeats at ~50ms intervals
        for (int i = 0; i < 5; i++) {
            detector.recordHeartbeat(NODE_A);
            Thread.sleep(50);
        }
        double phiSoon = detector.phi(NODE_A);

        // Wait significantly longer than the heartbeat interval
        Thread.sleep(300);
        double phiLater = detector.phi(NODE_A);

        assertTrue(phiLater > phiSoon,
                "phi should increase with elapsed time: soon=" + phiSoon + ", later=" + phiLater);
    }

    // --- Multiple nodes tracked independently ---

    @Test
    void nodesTrackedIndependently() throws InterruptedException {
        var detector = new PhiAccrualFailureDetector(10);

        // Record heartbeats for both nodes
        for (int i = 0; i < 3; i++) {
            detector.recordHeartbeat(NODE_A);
            detector.recordHeartbeat(NODE_B);
            Thread.sleep(50);
        }

        // Now stop heartbeating NODE_A but keep NODE_B going
        for (int i = 0; i < 3; i++) {
            detector.recordHeartbeat(NODE_B);
            Thread.sleep(50);
        }

        double phiA = detector.phi(NODE_A);
        double phiB = detector.phi(NODE_B);

        assertTrue(phiA > phiB,
                "NODE_A should have higher phi (no recent heartbeats): phiA=" + phiA + ", phiB=" + phiB);
    }

    // --- isAvailable ---

    @Test
    void isAvailableReturnsTrueForUnknownNode() {
        var detector = new PhiAccrualFailureDetector(10);
        // phi=0.0 for unknown node, which is below any positive threshold
        assertTrue(detector.isAvailable(NODE_A, 8.0));
    }

    @Test
    void isAvailableReturnsTrueWhenPhiBelowThreshold() throws InterruptedException {
        var detector = new PhiAccrualFailureDetector(10);
        detector.recordHeartbeat(NODE_A);
        Thread.sleep(50);
        detector.recordHeartbeat(NODE_A);
        // Just after a heartbeat, phi should be low
        assertTrue(detector.isAvailable(NODE_A, 8.0));
    }

    @Test
    void isAvailableReturnsFalseWhenPhiAboveThreshold() throws InterruptedException {
        var detector = new PhiAccrualFailureDetector(10);
        // Record heartbeats at fast interval
        for (int i = 0; i < 5; i++) {
            detector.recordHeartbeat(NODE_A);
            Thread.sleep(20);
        }

        // Wait long enough that phi exceeds a low threshold
        Thread.sleep(500);
        // Using a very low threshold to ensure the test passes
        assertFalse(detector.isAvailable(NODE_A, 0.5),
                "Node should be unavailable after long silence with low threshold");
    }

    // --- Window saturation ---

    @Test
    void windowSaturation() throws InterruptedException {
        // Window size of 3 — only the last 3 intervals should be retained
        var detector = new PhiAccrualFailureDetector(3);

        // Record 10 heartbeats — window should only keep last 3 intervals
        for (int i = 0; i < 10; i++) {
            detector.recordHeartbeat(NODE_A);
            Thread.sleep(20);
        }

        // The detector should still function correctly after window saturation
        double phi = detector.phi(NODE_A);
        assertTrue(phi >= 0.0, "phi should be non-negative after saturation");
        assertTrue(Double.isFinite(phi), "phi should be finite after saturation");
    }

    // --- Controllable time via overloaded recordHeartbeat ---

    @Test
    void phiComputationWithKnownIntervals() {
        var detector = new PhiAccrualFailureDetector(10);

        // Record heartbeats at exactly 1000ms intervals using nanoTime-based approach
        // We can test the math by recording heartbeats and checking relative phi values
        // Since the stub uses wall-clock time, this test validates the general contract
        detector.recordHeartbeat(NODE_A);
        // Force a known interval by immediately recording again
        // (phi should still be 0.0 with only 1 interval if elapsed is ~0)
        detector.recordHeartbeat(NODE_A);

        double phi = detector.phi(NODE_A);
        // With essentially zero elapsed time since last heartbeat and near-zero mean interval,
        // phi can be any non-negative value
        assertTrue(phi >= 0.0, "phi must be non-negative");
    }
}

package jlsm.engine.cluster;

import jlsm.engine.cluster.internal.GracePeriodManager;

import org.junit.jupiter.api.Test;

import java.time.Duration;
import java.time.Instant;
import java.util.Set;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Tests for {@link GracePeriodManager} — tracks departed nodes and manages
 * the grace period before permanent removal.
 */
final class GracePeriodManagerTest {

    private static final NodeAddress NODE_A = new NodeAddress("node-a", "host-a", 8001);
    private static final NodeAddress NODE_B = new NodeAddress("node-b", "host-b", 8002);
    private static final NodeAddress NODE_C = new NodeAddress("node-c", "host-c", 8003);
    private static final Duration GRACE = Duration.ofMinutes(5);
    private static final Instant BASE = Instant.parse("2026-03-20T00:00:00Z");

    // --- Constructor validation ---

    @Test
    void constructor_nullGracePeriodThrows() {
        assertThrows(NullPointerException.class, () -> new GracePeriodManager(null));
    }

    @Test
    void constructor_zeroGracePeriodThrows() {
        assertThrows(IllegalArgumentException.class,
                () -> new GracePeriodManager(Duration.ZERO));
    }

    @Test
    void constructor_negativeGracePeriodThrows() {
        assertThrows(IllegalArgumentException.class,
                () -> new GracePeriodManager(Duration.ofSeconds(-1)));
    }

    @Test
    void constructor_positiveGracePeriodSucceeds() {
        assertDoesNotThrow(() -> new GracePeriodManager(Duration.ofSeconds(1)));
    }

    // --- recordDeparture + isInGracePeriod ---

    @Test
    void isInGracePeriod_unknownNodeReturnsFalse() {
        GracePeriodManager mgr = new GracePeriodManager(GRACE);
        assertFalse(mgr.isInGracePeriod(NODE_A),
                "Unknown node should not be in grace period");
    }

    @Test
    void isInGracePeriod_withinGraceReturnsTrue() {
        GracePeriodManager mgr = new GracePeriodManager(GRACE);
        mgr.recordDeparture(NODE_A, BASE);
        // isInGracePeriod checks against current time — the departure was just recorded
        // and 5 minutes haven't passed yet in wall-clock time
        assertTrue(mgr.isInGracePeriod(NODE_A),
                "Recently departed node should be in grace period");
    }

    @Test
    void isInGracePeriod_afterGraceReturnsFalse() {
        // Use a very short grace period so wall-clock passes it
        GracePeriodManager mgr = new GracePeriodManager(Duration.ofNanos(1));
        mgr.recordDeparture(NODE_A, Instant.now().minusSeconds(1));
        assertFalse(mgr.isInGracePeriod(NODE_A),
                "Node whose grace period expired should not be in grace period");
    }

    // --- expiredDepartures ---

    @Test
    void expiredDepartures_emptyWhenNoDepartures() {
        GracePeriodManager mgr = new GracePeriodManager(GRACE);
        Set<NodeAddress> expired = mgr.expiredDepartures();
        assertNotNull(expired);
        assertTrue(expired.isEmpty());
    }

    @Test
    void expiredDepartures_returnsNodesAfterGrace() {
        GracePeriodManager mgr = new GracePeriodManager(Duration.ofNanos(1));
        mgr.recordDeparture(NODE_A, Instant.now().minusSeconds(1));
        mgr.recordDeparture(NODE_B, Instant.now().minusSeconds(1));

        Set<NodeAddress> expired = mgr.expiredDepartures();
        assertTrue(expired.contains(NODE_A));
        assertTrue(expired.contains(NODE_B));
    }

    @Test
    void expiredDepartures_excludesNodesStillInGrace() {
        GracePeriodManager mgr = new GracePeriodManager(Duration.ofHours(1));
        mgr.recordDeparture(NODE_A, Instant.now());
        mgr.recordDeparture(NODE_B, Instant.now());

        Set<NodeAddress> expired = mgr.expiredDepartures();
        assertTrue(expired.isEmpty(),
                "Nodes still within grace period should not appear as expired");
    }

    @Test
    void expiredDepartures_mixedGraceAndExpired() {
        // NODE_A: departed long ago (expired), NODE_B: departed now (in grace)
        GracePeriodManager mgr = new GracePeriodManager(Duration.ofMinutes(5));
        mgr.recordDeparture(NODE_A, Instant.now().minus(Duration.ofMinutes(10)));
        mgr.recordDeparture(NODE_B, Instant.now());

        Set<NodeAddress> expired = mgr.expiredDepartures();
        assertTrue(expired.contains(NODE_A), "NODE_A should be expired");
        assertFalse(expired.contains(NODE_B), "NODE_B should still be in grace");
    }

    // --- recordReturn ---

    @Test
    void recordReturn_cancelsGracePeriod() {
        GracePeriodManager mgr = new GracePeriodManager(GRACE);
        mgr.recordDeparture(NODE_A, BASE);
        assertTrue(mgr.isInGracePeriod(NODE_A));

        mgr.recordReturn(NODE_A);
        assertFalse(mgr.isInGracePeriod(NODE_A),
                "Returned node should no longer be in grace period");
    }

    @Test
    void recordReturn_removesFromExpiredDepartures() {
        GracePeriodManager mgr = new GracePeriodManager(Duration.ofNanos(1));
        mgr.recordDeparture(NODE_A, Instant.now().minusSeconds(1));
        // Should be expired now
        assertTrue(mgr.expiredDepartures().contains(NODE_A));

        mgr.recordReturn(NODE_A);
        assertFalse(mgr.expiredDepartures().contains(NODE_A),
                "Returned node should not appear in expired departures");
    }

    @Test
    void recordReturn_noopForUnknownNode() {
        GracePeriodManager mgr = new GracePeriodManager(GRACE);
        assertDoesNotThrow(() -> mgr.recordReturn(NODE_A),
                "Returning an unknown node should be a no-op");
    }

    // --- Input validation ---

    @Test
    void recordDeparture_nullNodeThrows() {
        GracePeriodManager mgr = new GracePeriodManager(GRACE);
        assertThrows(NullPointerException.class,
                () -> mgr.recordDeparture(null, BASE));
    }

    @Test
    void recordDeparture_nullInstantThrows() {
        GracePeriodManager mgr = new GracePeriodManager(GRACE);
        assertThrows(NullPointerException.class,
                () -> mgr.recordDeparture(NODE_A, null));
    }

    @Test
    void isInGracePeriod_nullNodeThrows() {
        GracePeriodManager mgr = new GracePeriodManager(GRACE);
        assertThrows(NullPointerException.class,
                () -> mgr.isInGracePeriod(null));
    }

    @Test
    void recordReturn_nullNodeThrows() {
        GracePeriodManager mgr = new GracePeriodManager(GRACE);
        assertThrows(NullPointerException.class,
                () -> mgr.recordReturn(null));
    }

    // --- Multiple departures of same node ---

    @Test
    void recordDeparture_updatesTimestampOnRedeparture() {
        GracePeriodManager mgr = new GracePeriodManager(Duration.ofMinutes(5));
        // First departure long ago
        mgr.recordDeparture(NODE_A, Instant.now().minus(Duration.ofMinutes(10)));
        assertTrue(mgr.expiredDepartures().contains(NODE_A));

        // Re-depart now — should reset grace window
        mgr.recordDeparture(NODE_A, Instant.now());
        assertTrue(mgr.isInGracePeriod(NODE_A),
                "Re-departure should reset the grace window");
        assertFalse(mgr.expiredDepartures().contains(NODE_A));
    }
}

package jlsm.engine.cluster;

import jlsm.engine.cluster.internal.InJvmDiscoveryProvider;
import jlsm.engine.cluster.internal.InJvmTransport;
import jlsm.engine.cluster.internal.PhiAccrualFailureDetector;
import jlsm.engine.cluster.internal.RapidMembership;

import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Tests for {@link RapidMembership}.
 */
class RapidMembershipTest {

    private static final NodeAddress ADDR_1 =
            new NodeAddress("node-1", "localhost", 8001);
    private static final NodeAddress ADDR_2 =
            new NodeAddress("node-2", "localhost", 8002);
    private static final NodeAddress ADDR_3 =
            new NodeAddress("node-3", "localhost", 8003);

    private final List<AutoCloseable> closeables = new ArrayList<>();

    @BeforeEach
    void setUp() {
        InJvmTransport.clearRegistry();
        InJvmDiscoveryProvider.clearRegistrations();
    }

    @AfterEach
    void tearDown() throws Exception {
        Exception first = null;
        for (int i = closeables.size() - 1; i >= 0; i--) {
            try {
                closeables.get(i).close();
            } catch (Exception e) {
                if (first == null) first = e;
                else first.addSuppressed(e);
            }
        }
        closeables.clear();
        InJvmTransport.clearRegistry();
        InJvmDiscoveryProvider.clearRegistrations();
        if (first != null) throw first;
    }

    // --- Constructor validation ---

    @Test
    void constructorRejectsNullLocalAddress() {
        var transport = createTransport(ADDR_1);
        var discovery = new InJvmDiscoveryProvider();
        var config = ClusterConfig.builder().build();
        var detector = new PhiAccrualFailureDetector(10);
        assertThrows(NullPointerException.class,
                () -> new RapidMembership(null, transport, discovery, config, detector));
    }

    @Test
    void constructorRejectsNullTransport() {
        var discovery = new InJvmDiscoveryProvider();
        var config = ClusterConfig.builder().build();
        var detector = new PhiAccrualFailureDetector(10);
        assertThrows(NullPointerException.class,
                () -> new RapidMembership(ADDR_1, null, discovery, config, detector));
    }

    @Test
    void constructorRejectsNullDiscovery() {
        var transport = createTransport(ADDR_1);
        var config = ClusterConfig.builder().build();
        var detector = new PhiAccrualFailureDetector(10);
        assertThrows(NullPointerException.class,
                () -> new RapidMembership(ADDR_1, transport, null, config, detector));
    }

    @Test
    void constructorRejectsNullConfig() {
        var transport = createTransport(ADDR_1);
        var discovery = new InJvmDiscoveryProvider();
        var detector = new PhiAccrualFailureDetector(10);
        assertThrows(NullPointerException.class,
                () -> new RapidMembership(ADDR_1, transport, discovery, null, detector));
    }

    @Test
    void constructorRejectsNullFailureDetector() {
        var transport = createTransport(ADDR_1);
        var discovery = new InJvmDiscoveryProvider();
        var config = ClusterConfig.builder().build();
        assertThrows(NullPointerException.class,
                () -> new RapidMembership(ADDR_1, transport, discovery, config, null));
    }

    // --- Single node cluster ---

    @Test
    void singleNodeStartsCluster() throws Exception {
        var membership = createMembership(ADDR_1);
        membership.start(List.of());

        MembershipView view = membership.currentView();
        assertNotNull(view, "view should not be null after start");
        assertEquals(1, view.members().size(),
                "single-node cluster should have 1 member");
        assertTrue(view.isMember(ADDR_1),
                "local node should be a member of its own cluster");
    }

    @Test
    void singleNodeViewHasEpochZeroOrHigher() throws Exception {
        var membership = createMembership(ADDR_1);
        membership.start(List.of());

        MembershipView view = membership.currentView();
        assertTrue(view.epoch() >= 0, "epoch should be non-negative");
    }

    // --- addListener ---

    @Test
    void addListenerRejectsNull() throws Exception {
        var membership = createMembership(ADDR_1);
        assertThrows(NullPointerException.class,
                () -> membership.addListener(null));
    }

    // --- Multi-node cluster formation ---

    @Test
    void twoNodeClusterFormation() throws Exception {
        var discovery = new InJvmDiscoveryProvider();

        var m1 = createMembership(ADDR_1, discovery);
        m1.start(List.of());
        discovery.register(ADDR_1);

        var m2 = createMembership(ADDR_2, discovery);
        m2.start(List.of(ADDR_1));

        // Give the protocol time to converge
        Thread.sleep(500);

        MembershipView view1 = m1.currentView();
        MembershipView view2 = m2.currentView();

        // Both nodes should see each other
        assertTrue(view1.isMember(ADDR_1), "node-1 should see itself");
        assertTrue(view1.isMember(ADDR_2), "node-1 should see node-2");
        assertTrue(view2.isMember(ADDR_1), "node-2 should see node-1");
        assertTrue(view2.isMember(ADDR_2), "node-2 should see itself");
    }

    @Test
    void threeNodeClusterFormation() throws Exception {
        var discovery = new InJvmDiscoveryProvider();

        var m1 = createMembership(ADDR_1, discovery);
        m1.start(List.of());
        discovery.register(ADDR_1);

        var m2 = createMembership(ADDR_2, discovery);
        m2.start(List.of(ADDR_1));
        discovery.register(ADDR_2);

        var m3 = createMembership(ADDR_3, discovery);
        m3.start(List.of(ADDR_1));

        // Give the protocol time to converge
        Thread.sleep(500);

        MembershipView view1 = m1.currentView();
        assertEquals(3, view1.members().size(),
                "all 3 nodes should be in the cluster view");
    }

    // --- Listener callbacks ---

    @Test
    void listenerNotifiedOnMemberJoin() throws Exception {
        var discovery = new InJvmDiscoveryProvider();
        var joinedMembers = new CopyOnWriteArrayList<Member>();
        var latch = new CountDownLatch(1);

        var m1 = createMembership(ADDR_1, discovery);
        m1.addListener(new MembershipListener() {
            @Override
            public void onViewChanged(MembershipView oldView, MembershipView newView) {}

            @Override
            public void onMemberJoined(Member member) {
                joinedMembers.add(member);
                latch.countDown();
            }

            @Override
            public void onMemberLeft(Member member) {}

            @Override
            public void onMemberSuspected(Member member) {}
        });
        m1.start(List.of());
        discovery.register(ADDR_1);

        var m2 = createMembership(ADDR_2, discovery);
        m2.start(List.of(ADDR_1));

        boolean notified = latch.await(2, TimeUnit.SECONDS);
        assertTrue(notified, "listener should be notified when a member joins");
        assertFalse(joinedMembers.isEmpty(), "at least one member-joined event expected");
    }

    @Test
    void listenerNotifiedOnViewChange() throws Exception {
        var discovery = new InJvmDiscoveryProvider();
        var viewChanges = new CopyOnWriteArrayList<MembershipView>();
        var latch = new CountDownLatch(1);

        var m1 = createMembership(ADDR_1, discovery);
        m1.addListener(new MembershipListener() {
            @Override
            public void onViewChanged(MembershipView oldView, MembershipView newView) {
                viewChanges.add(newView);
                latch.countDown();
            }

            @Override
            public void onMemberJoined(Member member) {}

            @Override
            public void onMemberLeft(Member member) {}

            @Override
            public void onMemberSuspected(Member member) {}
        });
        m1.start(List.of());
        discovery.register(ADDR_1);

        var m2 = createMembership(ADDR_2, discovery);
        m2.start(List.of(ADDR_1));

        boolean notified = latch.await(2, TimeUnit.SECONDS);
        assertTrue(notified, "listener should be notified of view changes");
    }

    // --- Graceful leave ---

    @Test
    void leaveRemovesNodeFromView() throws Exception {
        var discovery = new InJvmDiscoveryProvider();

        var m1 = createMembership(ADDR_1, discovery);
        m1.start(List.of());
        discovery.register(ADDR_1);

        var m2 = createMembership(ADDR_2, discovery);
        m2.start(List.of(ADDR_1));

        Thread.sleep(500);

        // Verify both nodes are in the view
        assertEquals(2, m1.currentView().members().size());

        // Node 2 leaves gracefully
        m2.leave();

        Thread.sleep(500);

        // Node 1 should eventually see node 2 as removed or dead
        MembershipView view1 = m1.currentView();
        long aliveCount = view1.members().stream()
                .filter(m -> m.state() == MemberState.ALIVE)
                .count();
        assertEquals(1, aliveCount,
                "after leave, only 1 node should be ALIVE in node-1's view");
    }

    // --- Close ---

    @Test
    void closeIsIdempotent() throws Exception {
        var membership = createMembership(ADDR_1);
        membership.start(List.of());
        membership.close();
        assertDoesNotThrow(() -> membership.close(),
                "close() should be idempotent");
    }

    @Test
    void currentViewAfterStartReturnsNonNull() throws Exception {
        var membership = createMembership(ADDR_1);
        membership.start(List.of());
        assertNotNull(membership.currentView());
    }

    // --- Epoch progression ---

    @Test
    void epochIncreasesOnViewChange() throws Exception {
        var discovery = new InJvmDiscoveryProvider();

        var m1 = createMembership(ADDR_1, discovery);
        m1.start(List.of());
        discovery.register(ADDR_1);

        long initialEpoch = m1.currentView().epoch();

        var m2 = createMembership(ADDR_2, discovery);
        m2.start(List.of(ADDR_1));

        Thread.sleep(500);

        long newEpoch = m1.currentView().epoch();
        assertTrue(newEpoch > initialEpoch,
                "epoch should increase after a view change: initial=" + initialEpoch + ", new=" + newEpoch);
    }

    // --- Helpers ---

    private InJvmTransport createTransport(NodeAddress addr) {
        var transport = new InJvmTransport(addr);
        closeables.add(transport);
        return transport;
    }

    private RapidMembership createMembership(NodeAddress addr) {
        return createMembership(addr, new InJvmDiscoveryProvider());
    }

    private RapidMembership createMembership(NodeAddress addr, DiscoveryProvider discovery) {
        var transport = createTransport(addr);
        var config = ClusterConfig.builder()
                .protocolPeriod(java.time.Duration.ofMillis(100))
                .pingTimeout(java.time.Duration.ofMillis(50))
                .build();
        var detector = new PhiAccrualFailureDetector(10);
        var membership = new RapidMembership(addr, transport, discovery, config, detector);
        closeables.add(membership);
        return membership;
    }
}

package jlsm.engine.cluster.internal;

import jlsm.engine.cluster.Member;
import jlsm.engine.cluster.MemberState;
import jlsm.engine.cluster.MembershipView;
import jlsm.engine.cluster.NodeAddress;

import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Objects;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Deterministic partition-to-node ownership via Rendezvous (Highest Random Weight) hashing.
 *
 * <p>
 * Contract: Pure function of (identifier, membership view). Given the same view, all nodes
 * compute the same ownership assignment. For each table or partition ID, computes
 * hash(id, node_id) for all live nodes in the view and assigns to the node with the
 * highest weight. Results are cached keyed on view epoch to avoid redundant computation.
 *
 * <p>
 * Thread-safe: uses concurrent cache and pure computations.
 *
 * <p>
 * Governed by: {@code .decisions/partition-to-node-ownership/adr.md}
 */
public final class RendezvousOwnership {

    private final ConcurrentHashMap<Long, ConcurrentHashMap<String, NodeAddress>> cache =
            new ConcurrentHashMap<>();

    /**
     * Assigns a single owner for the given identifier within the current membership view.
     *
     * @param id   the table or partition identifier; must not be null or empty
     * @param view the current membership view; must not be null
     * @return the owning node's address; never null
     * @throws IllegalStateException if the view contains no live members
     */
    public NodeAddress assignOwner(String id, MembershipView view) {
        Objects.requireNonNull(id, "id must not be null");
        Objects.requireNonNull(view, "view must not be null");
        if (id.isEmpty()) {
            throw new IllegalArgumentException("id must not be empty");
        }

        final ConcurrentHashMap<String, NodeAddress> epochCache =
                cache.computeIfAbsent(view.epoch(), _ -> new ConcurrentHashMap<>());

        final NodeAddress cached = epochCache.get(id);
        if (cached != null) {
            return cached;
        }

        final List<NodeAddress> ranked = computeRankedOwners(id, view);
        assert !ranked.isEmpty() : "ranked list must not be empty after live-member check";

        final NodeAddress owner = ranked.getFirst();
        epochCache.put(id, owner);
        return owner;
    }

    /**
     * Assigns multiple owners (for future replication) ranked by weight.
     *
     * @param id       the table or partition identifier; must not be null or empty
     * @param view     the current membership view; must not be null
     * @param replicas the number of owners to assign; must be >= 1
     * @return a list of node addresses ranked by weight, up to {@code replicas} or the number
     *         of live members, whichever is smaller; never null or empty
     * @throws IllegalStateException if the view contains no live members
     */
    public List<NodeAddress> assignOwners(String id, MembershipView view, int replicas) {
        Objects.requireNonNull(id, "id must not be null");
        Objects.requireNonNull(view, "view must not be null");
        if (id.isEmpty()) {
            throw new IllegalArgumentException("id must not be empty");
        }
        if (replicas < 1) {
            throw new IllegalArgumentException("replicas must be >= 1, got: " + replicas);
        }

        final List<NodeAddress> ranked = computeRankedOwners(id, view);
        assert !ranked.isEmpty() : "ranked list must not be empty after live-member check";

        final int count = Math.min(replicas, ranked.size());
        return List.copyOf(ranked.subList(0, count));
    }

    /**
     * Invalidates cached assignments for views older than the given epoch.
     *
     * @param currentEpoch the current epoch; entries for older epochs are evicted
     */
    public void evictBefore(long currentEpoch) {
        cache.keySet().removeIf(epoch -> epoch < currentEpoch);
    }

    /**
     * Computes the full ranking of live members for the given id, sorted by descending
     * HRW weight. Ties are broken by nodeId for determinism.
     */
    private List<NodeAddress> computeRankedOwners(String id, MembershipView view) {
        final List<WeightedNode> weighted = new ArrayList<>();
        final byte[] idBytes = id.getBytes(StandardCharsets.UTF_8);

        for (Member member : view.members()) {
            if (member.state() != MemberState.ALIVE) {
                continue;
            }
            final byte[] nodeBytes = member.address().nodeId().getBytes(StandardCharsets.UTF_8);
            final long weight = hrwHash(idBytes, nodeBytes);
            weighted.add(new WeightedNode(member.address(), weight));
        }

        if (weighted.isEmpty()) {
            throw new IllegalStateException("No live members in the membership view");
        }

        // Sort by weight descending, then by nodeId ascending for deterministic tie-breaking
        weighted.sort(Comparator.comparingLong(WeightedNode::weight).reversed()
                .thenComparing(wn -> wn.address().nodeId()));

        final List<NodeAddress> result = new ArrayList<>(weighted.size());
        for (WeightedNode wn : weighted) {
            result.add(wn.address());
        }
        assert result.size() == weighted.size() : "result size must match weighted size";
        return result;
    }

    /**
     * Computes a hash weight for the (id, nodeId) pair using a SipHash-inspired mixing
     * function. The result is deterministic and uniformly distributed.
     */
    private static long hrwHash(byte[] idBytes, byte[] nodeBytes) {
        // Combine id and nodeId bytes with a simple but effective mixing strategy.
        // Use FNV-1a variant for fast, well-distributed hashing.
        long hash = 0xcbf29ce484222325L; // FNV offset basis
        final long prime = 0x100000001b3L;  // FNV prime

        for (byte b : idBytes) {
            hash ^= (b & 0xffL);
            hash *= prime;
        }
        // Separator to prevent collisions between ("ab","cd") and ("abc","d")
        hash ^= 0xffL;
        hash *= prime;

        for (byte b : nodeBytes) {
            hash ^= (b & 0xffL);
            hash *= prime;
        }

        // Finalizer mix (Stafford variant 13)
        hash ^= (hash >>> 30);
        hash *= 0xbf58476d1ce4e5b9L;
        hash ^= (hash >>> 27);
        hash *= 0x94d049bb133111ebL;
        hash ^= (hash >>> 31);

        return hash;
    }

    private record WeightedNode(NodeAddress address, long weight) {}
}

