100→        checkNotClosed();
101→
102→        final NodeAddress owner = resolveOwner(key);
103→        final RemotePartitionClient client = createClient(key, owner);
104→        try {
105→            client.update(key, doc, mode);
106→        } finally {
107→            client.close();
108→        }
109→    }
