112→    public void delete(String key) throws IOException {
113→        Objects.requireNonNull(key, "key must not be null");
114→        checkNotClosed();
115→
116→        final NodeAddress owner = resolveOwner(key);
117→        final RemotePartitionClient client = createClient(key, owner);
118→        try {
119→            client.delete(key);
120→        } finally {
121→            client.close();
122→        }
123→    }
