126→    public void insert(JlsmDocument doc) throws IOException {
127→        Objects.requireNonNull(doc, "doc must not be null");
128→        checkNotClosed();
129→        // Insert without an explicit key requires the schema-defined primary key.
130→        // For now, delegate to the first live node.
131→        throw new UnsupportedOperationException(
132→                "insert without explicit key is not yet supported in clustered mode");
133→    }
134→
135→    @Override
136→    public TableQuery<String> query() {
137→        checkNotClosedUnchecked();
138→        throw new UnsupportedOperationException(
139→                "TableQuery is not yet supported in clustered mode; use scan() instead");
140→    }
141→
142→    @Override
143→    public Iterator<TableEntry<String>> scan(String fromKey, String toKey) throws IOException {
144→        Objects.requireNonNull(fromKey, "fromKey must not be null");
145→        Objects.requireNonNull(toKey, "toKey must not be null");
146→        checkNotClosed();
147→
148→        final MembershipView view = membership.currentView();
149→        final Set<NodeAddress> liveNodes = collectLiveNodes(view);
150→
151→        if (liveNodes.isEmpty()) {
152→            lastPartialResult = new PartialResultMetadata(Set.of("all"), false);
153→            return Collections.emptyIterator();
154→        }
155→
156→        final List<Iterator<TableEntry<String>>> iterators = new ArrayList<>();
157→        final Set<String> unavailable = new HashSet<>();
158→
159→        // Scatter: send range query to all live nodes
160→        for (final NodeAddress node : liveNodes) {
161→            final RemotePartitionClient client = createClientForNode(node);
162→            try {
163→                final Iterator<TableEntry<String>> it = client.getRange(fromKey, toKey);
164→                iterators.add(it);
165→            } catch (IOException e) {
166→                unavailable.add(node.nodeId());
167→            }
168→        }
169→
170→        lastPartialResult = new PartialResultMetadata(
171→                Set.copyOf(unavailable), unavailable.isEmpty());
172→
173→        // K-way merge the iterators by key order
174→        return mergeOrdered(iterators);
175→    }
