200→     * Uses the table name as the partition identifier for ownership.
201→     */
202→    private NodeAddress resolveOwner(String key) {
203→        assert key != null : "key must not be null";
204→        final MembershipView view = membership.currentView();
205→        final Set<NodeAddress> liveNodes = collectLiveNodes(view);
206→        if (liveNodes.isEmpty()) {
207→            throw new IllegalStateException("No live members in the cluster");
208→        }
