216→     */
217→    private Set<NodeAddress> collectLiveNodes(MembershipView view) {
218→        assert view != null : "view must not be null";
219→        final Set<NodeAddress> result = new HashSet<>();
220→        for (final Member m : view.members()) {
221→            if (m.state() == MemberState.ALIVE) {
222→                result.add(m.address());
223→            }
224→        }
225→        return result;
226→    }
227→
228→    /**
229→     * Creates a RemotePartitionClient for a key-specific operation routed to the owner.
230→     */
231→    private RemotePartitionClient createClient(String key, NodeAddress owner) {
232→        assert key != null : "key must not be null";
233→        assert owner != null : "owner must not be null";
234→        final PartitionDescriptor desc = new PartitionDescriptor(
235→                0L,
236→                java.lang.foreign.MemorySegment.ofArray(new byte[0]),
237→                java.lang.foreign.MemorySegment.ofArray(new byte[0]),
238→                owner.nodeId(),
239→                0L
240→        );
241→        return new RemotePartitionClient(desc, owner, transport, findLocalAddress());
242→    }
243→
244→    /**
245→     * Creates a RemotePartitionClient for a specific target node (used in scatter).
246→     */
247→    private RemotePartitionClient createClientForNode(NodeAddress target) {
248→        assert target != null : "target must not be null";
249→        final PartitionDescriptor desc = new PartitionDescriptor(
250→                0L,
251→                java.lang.foreign.MemorySegment.ofArray(new byte[0]),
252→                java.lang.foreign.MemorySegment.ofArray(new byte[0]),
253→                target.nodeId(),
254→                0L
255→        );
256→        return new RemotePartitionClient(desc, target, transport, findLocalAddress());
257→    }
258→
259→    /**
260→     * Returns the local address by inspecting the membership view for any node that
261→     * might be local. Falls back to the first live member.
262→     */
263→    private NodeAddress findLocalAddress() {
264→        final MembershipView view = membership.currentView();
265→        for (final Member m : view.members()) {
266→            if (m.state() == MemberState.ALIVE) {
267→                return m.address();
268→            }
269→        }
270→        throw new IllegalStateException("No live members available for local address resolution");
271→    }
272→
273→    /**
274→     * Performs a k-way merge of sorted iterators using a min-heap.
275→     * Each iterator must be sorted by key in natural order.
276→     *
277→     * @param iterators the sorted iterators to merge
278→     * @return a merged iterator producing entries in global key order
279→     */
280→    private static Iterator<TableEntry<String>> mergeOrdered(
281→            List<Iterator<TableEntry<String>>> iterators) {
282→        assert iterators != null : "iterators must not be null";
283→
284→        if (iterators.isEmpty()) {
285→            return Collections.emptyIterator();
286→        }
287→        if (iterators.size() == 1) {
288→            return iterators.getFirst();
289→        }
290→
291→        // Initialize min-heap with first element from each iterator
292→        final PriorityQueue<HeapEntry> heap = new PriorityQueue<>(
293→                iterators.size(),
294→                Comparator.comparing(he -> he.current.key())
295→        );
296→
297→        for (int i = 0; i < iterators.size(); i++) {
298→            final Iterator<TableEntry<String>> it = iterators.get(i);
299→            if (it.hasNext()) {
300→                heap.offer(new HeapEntry(it.next(), it));
301→            }
302→        }
303→
304→        return new Iterator<>() {
305→            @Override
306→            public boolean hasNext() {
307→                return !heap.isEmpty();
308→            }
309→
310→            @Override
311→            public TableEntry<String> next() {
312→                if (!hasNext()) {
313→                    throw new NoSuchElementException();
314→                }
315→                final HeapEntry entry = heap.poll();
316→                assert entry != null : "heap entry must not be null";
317→                final TableEntry<String> result = entry.current;
318→
319→                // Advance the source iterator
320→                if (entry.source.hasNext()) {
321→                    heap.offer(new HeapEntry(entry.source.next(), entry.source));
322→                }
323→                return result;
324→            }
325→        };
326→    }
327→
328→    private void checkNotClosed() throws IOException {
329→        if (closed) {
330→            throw new IOException("ClusteredTable is closed");
331→        }
332→    }
333→
334→    private void checkNotClosedUnchecked() {
335→        if (closed) {
336→            throw new IllegalStateException("ClusteredTable is closed");
337→        }
338→    }
339→
340→    /**
341→     * Entry in the k-way merge heap.
342→     */
343→    private record HeapEntry(TableEntry<String> current, Iterator<TableEntry<String>> source) {
344→        HeapEntry {
345→            assert current != null : "current must not be null";
346→            assert source != null : "source must not be null";
347→        }
348→    }
349→}
